      Object? includes = matrix is Map ? matrix[m.group(1)] : null;
      if (matrix is Map && matrix['include'] is Iterable) {
        for (final inc in matrix['include'] as Iterable) {
          if (inc is Map && inc.containsKey(m.group(1))) {
            includes = inc[m.group(1)];
